-- Esquema PostgreSQL convertido desde db/esquema_completo.sql.
-- Ejecutar sobre la base ANPR_ECU911 con psql. Los IDs se mantienen como
-- GENERATED BY DEFAULT para permitir importar volcados que incluyan IDs.

CREATE TABLE IF NOT EXISTS "roles" (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  codigo varchar(20) NOT NULL UNIQUE,
  nombre varchar(50) NOT NULL,
  descripcion varchar(255)
);

CREATE TABLE IF NOT EXISTS "usuarios" (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email varchar(150) NOT NULL UNIQUE,
  nombre_completo varchar(150) NOT NULL,
  cargo varchar(100),
  password_hash varchar(100) NOT NULL,
  rol_id integer NOT NULL REFERENCES "roles"(id),
  estado varchar(20) NOT NULL DEFAULT 'pendiente' CHECK (estado IN ('inactivo','activo','pendiente')),
  email_verificado boolean NOT NULL DEFAULT false,
  bloqueado boolean NOT NULL DEFAULT false,
  bloqueado_hasta timestamp,
  intentos_fallidos integer NOT NULL DEFAULT 0,
  fecha_ultimo_acceso timestamp,
  fecha_cambio_password timestamp,
  creado_por integer REFERENCES "usuarios"(id),
  fecha_creacion timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  fecha_actualizacion timestamp
);

CREATE TABLE IF NOT EXISTS "auditoriaaccesos" (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  fecha timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  email varchar(150) NOT NULL,
  usuario_id integer REFERENCES "usuarios"(id),
  exito boolean NOT NULL,
  motivo varchar(50), ip varchar(45), user_agent varchar(255)
);
CREATE TABLE IF NOT EXISTS "auditoriaaccesosarchivo" (
  id bigint PRIMARY KEY, fecha timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  email varchar(150) NOT NULL, usuario_id integer REFERENCES "usuarios"(id),
  exito boolean NOT NULL, motivo varchar(50), ip varchar(45), user_agent varchar(255),
  fecha_archivado timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "auditoriaconsultapropietario" (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  usuario_id integer NOT NULL REFERENCES "usuarios"(id), usuario_nombre varchar(100),
  placa varchar(20) NOT NULL, motivo varchar(255) NOT NULL, deteccion_id integer,
  proveedor varchar(50) NOT NULL, resultado varchar(20) NOT NULL,
  fecha timestamp DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "auditoriadescartes" (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tracking_id integer, motivo varchar(100) NOT NULL, texto_candidato varchar(50),
  confianza double precision, fuente varchar(255), camara_id integer,
  fecha_registro timestamp DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "auditoriaoperaciones" (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  fecha timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, usuario_id integer REFERENCES "usuarios"(id),
  usuario_email varchar(150), accion varchar(50) NOT NULL, entidad varchar(40) NOT NULL,
  entidad_id integer, detalle varchar(500), ip varchar(45)
);
CREATE TABLE IF NOT EXISTS "auditoriaoperacionesarchivo" (
  id bigint PRIMARY KEY, fecha timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  usuario_id integer REFERENCES "usuarios"(id), usuario_email varchar(150),
  accion varchar(50) NOT NULL, entidad varchar(40) NOT NULL, entidad_id integer,
  detalle varchar(500), ip varchar(45), fecha_archivado timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "auditoriausuarios" (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  fecha timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, accion varchar(50) NOT NULL,
  actor_id integer REFERENCES "usuarios"(id), actor_email varchar(150), objetivo_id integer,
  objetivo_email varchar(150), detalle varchar(500), ip varchar(45)
);
CREATE TABLE IF NOT EXISTS "auditoriausuariosarchivo" (
  id bigint PRIMARY KEY, fecha timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  accion varchar(50) NOT NULL, actor_id integer REFERENCES "usuarios"(id),
  actor_email varchar(150), objetivo_id integer, objetivo_email varchar(150),
  detalle varchar(500), ip varchar(45), fecha_archivado timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "camaras" (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nombre varchar(100) NOT NULL, ip varchar(45) NOT NULL, rtsp_url varchar(512) NOT NULL,
  ubicacion varchar(150) NOT NULL, activa boolean DEFAULT true,
  created_at timestamp DEFAULT CURRENT_TIMESTAMP, estado varchar(20) DEFAULT 'ACTIVA',
  ultimo_ping timestamp, tiempo_respuesta_ms integer, mensaje_ping varchar(255),
  registrado_por integer REFERENCES "usuarios"(id), fecha_actualizacion timestamp,
  direccion varchar(10) NOT NULL DEFAULT 'ingreso' CHECK (direccion IN ('ingreso','salida')),
  roi varchar(1000), rtsp_url_vista varchar(512), exclusiones text
);
CREATE TABLE IF NOT EXISTS "clavesservicio" (
  clave varchar(60) PRIMARY KEY, valor varchar(1000) NOT NULL,
  fecha_creacion timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "configuracionsistema" (
  clave varchar(60) PRIMARY KEY, valor varchar(500) NOT NULL,
  actualizado_por integer REFERENCES "usuarios"(id), fecha_actualizacion timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "listanegra" (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  placa varchar(10) NOT NULL UNIQUE, motivo varchar(255) NOT NULL,
  nivel_alerta varchar(20) DEFAULT 'ALTA' CHECK (nivel_alerta IN ('MEDIA','ALTA','CRITICA')),
  fecha_registro timestamp DEFAULT CURRENT_TIMESTAMP, activo boolean DEFAULT true,
  marca varchar(50), modelo varchar(50), color varchar(30),
  registrado_por integer REFERENCES "usuarios"(id), fecha_actualizacion timestamp,
  fecha_vencimiento date, observaciones varchar(255)
);
CREATE TABLE IF NOT EXISTS "vehiculosautorizados" (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  placa varchar(10) NOT NULL UNIQUE, propietario varchar(150) NOT NULL, departamento varchar(100),
  tipo_vehiculo varchar(50), activo boolean DEFAULT true, fecha_registro timestamp DEFAULT CURRENT_TIMESTAMP,
  marca varchar(50), modelo varchar(50), color varchar(30), registrado_por integer REFERENCES "usuarios"(id),
  fecha_actualizacion timestamp, fecha_vencimiento date, observaciones varchar(255),
  categoria varchar(20) NOT NULL DEFAULT 'FUNCIONARIO' CHECK (categoria IN ('EMERGENCIA','OFICIAL','CONTRATISTA','PROVEEDOR','VISITANTE','FUNCIONARIO')),
  fecha_inicio date, horario varchar(600), solicitud_id integer
);
CREATE TABLE IF NOT EXISTS "deteccionvehiculo" (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  confianza_deteccion double precision, confianza_ocr double precision,
  tracking_id integer DEFAULT -1, fuente varchar(255) DEFAULT 'rtsp',
  tipo_movimiento varchar(10) NOT NULL DEFAULT 'ingreso' CHECK (tipo_movimiento IN ('ingreso','salida')),
  estado_validacion varchar(30) DEFAULT 'no_reconocido',
  camara_id integer REFERENCES "camaras"(id), alerta_id integer REFERENCES "listanegra"(id),
  vehiculo_autorizado_id integer REFERENCES "vehiculosautorizados"(id),
  estado_procesamiento varchar(30) DEFAULT 'pendiente_ocr', ruta_imagen_ingreso varchar(255),
  ruta_imagen_placa varchar(255), fecha_hora_ingreso timestamp DEFAULT CURRENT_TIMESTAMP,
  placa_reconocida varchar(20), fecha_hora_procesamiento timestamp,
  validado_manualmente boolean DEFAULT false, placa_validada varchar(20),
  usuario_validador_id integer REFERENCES "usuarios"(id), tipo_vehiculo varchar(50),
  placa_ocr_original varchar(20), confianza_ocr_original double precision,
  decision_automatica varchar(30), lectura_verificador varchar(20), latencia_ms integer,
  luminancia_media double precision, distancia_estimada_m double precision, ancho_placa_px integer,
  nitidez double precision, velocidad_px_s double precision, condicion_clima varchar(20),
  modelo_detector varchar(100), modelo_ocr varchar(100), fecha_validacion timestamp,
  vehiculo_tipo varchar(30), vehiculo_color varchar(30), vehiculo_marca varchar(50),
  vehiculo_modelo varchar(50), vehiculo_atributos_json varchar(500),
  verificacion_vehiculo varchar(20), verificacion_detalle varchar(255), lectura_valida boolean,
  evidencia_lectura varchar(1500), restriccion_acceso varchar(30)
);
CREATE TABLE IF NOT EXISTS "notificaciones" (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tipo varchar(40) NOT NULL,
  severidad varchar(10) NOT NULL CHECK (severidad IN ('baja','media','alta','critica')),
  titulo varchar(150) NOT NULL, mensaje varchar(500) NOT NULL, enlace varchar(200), datos varchar(1000),
  clave_dedup varchar(120), repeticiones integer NOT NULL DEFAULT 1,
  requiere_ack boolean NOT NULL DEFAULT false, deteccion_id integer REFERENCES "deteccionvehiculo"(id) ON DELETE SET NULL,
  fecha_creacion timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, fecha_ultima timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  atendida_por integer REFERENCES "usuarios"(id), fecha_atencion timestamp, fecha_resolucion timestamp,
  escalada boolean NOT NULL DEFAULT false, fecha_escalamiento timestamp
);
CREATE TABLE IF NOT EXISTS "notificacionusuario" (
  notificacion_id bigint NOT NULL REFERENCES "notificaciones"(id) ON DELETE CASCADE,
  usuario_id integer NOT NULL REFERENCES "usuarios"(id) ON DELETE CASCADE,
  fecha_lectura timestamp, fecha_eliminacion timestamp,
  PRIMARY KEY (notificacion_id, usuario_id)
);
CREATE TABLE IF NOT EXISTS "restablecimientopassword" (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, usuario_id integer NOT NULL REFERENCES "usuarios"(id) ON DELETE CASCADE,
  token_hash char(64) NOT NULL, fecha_creacion timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  fecha_expiracion timestamp NOT NULL, usado boolean NOT NULL DEFAULT false, fecha_uso timestamp
);
CREATE TABLE IF NOT EXISTS "schemamigraciones" (
  nombre varchar(120) PRIMARY KEY, suma_sha256 char(64) NOT NULL,
  fecha_aplicada timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "solicitudesacceso" (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, placa varchar(10) NOT NULL,
  propietario varchar(150) NOT NULL, departamento varchar(100), categoria varchar(20) NOT NULL DEFAULT 'VISITANTE',
  motivo varchar(300) NOT NULL, tipo_vehiculo varchar(50), marca varchar(50), modelo varchar(50), color varchar(30),
  fecha_inicio date, fecha_fin date, horario varchar(600), deteccion_id integer REFERENCES "deteccionvehiculo"(id) ON DELETE SET NULL,
  estado varchar(20) NOT NULL DEFAULT 'pendiente' CHECK (estado IN ('cancelada','rechazada','aprobada','pendiente')),
  solicitado_por integer NOT NULL REFERENCES "usuarios"(id), fecha_solicitud timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  resuelto_por integer REFERENCES "usuarios"(id), fecha_resolucion timestamp, comentario_resolucion varchar(300),
  vehiculo_autorizado_id integer REFERENCES "vehiculosautorizados"(id), version integer NOT NULL DEFAULT 1
);
CREATE TABLE IF NOT EXISTS "suscripcionespush" (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, usuario_id integer NOT NULL REFERENCES "usuarios"(id) ON DELETE CASCADE,
  endpoint varchar(600) NOT NULL, endpoint_hash char(64) NOT NULL UNIQUE, p256dh varchar(200) NOT NULL,
  auth varchar(100) NOT NULL, user_agent varchar(255), fecha_creacion timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  fecha_ultimo_uso timestamp, fallos integer NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS "verificacionemail" (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, usuario_id integer NOT NULL REFERENCES "usuarios"(id) ON DELETE CASCADE,
  token_hash char(64) NOT NULL, fecha_creacion timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  fecha_expiracion timestamp NOT NULL, usado boolean NOT NULL DEFAULT false, fecha_uso timestamp
);

CREATE INDEX IF NOT EXISTS ix_usuarios_rol_estado ON "usuarios" (rol_id, estado);
CREATE INDEX IF NOT EXISTS ix_auditoriaaccesos_email ON "auditoriaaccesos" (email, fecha DESC);
CREATE INDEX IF NOT EXISTS ix_auditoriaaccesos_fecha ON "auditoriaaccesos" (fecha DESC);
CREATE INDEX IF NOT EXISTS ix_auditoriaaccesosarchivo_fecha ON "auditoriaaccesosarchivo" (fecha DESC);
CREATE INDEX IF NOT EXISTS ix_auditoriapropietario_fecha ON "auditoriaconsultapropietario" (fecha);
CREATE INDEX IF NOT EXISTS ix_auditoriapropietario_usuario ON "auditoriaconsultapropietario" (usuario_id, fecha);
CREATE INDEX IF NOT EXISTS ix_auditoriadescartes_fecha ON "auditoriadescartes" (fecha_registro);
CREATE INDEX IF NOT EXISTS ix_auditoriaoperaciones_entidad ON "auditoriaoperaciones" (entidad, entidad_id);
CREATE INDEX IF NOT EXISTS ix_auditoriaoperaciones_fecha ON "auditoriaoperaciones" (fecha DESC);
CREATE INDEX IF NOT EXISTS ix_auditoriaoperacionesarchivo_fecha ON "auditoriaoperacionesarchivo" (fecha DESC);
CREATE INDEX IF NOT EXISTS ix_auditoriausuarios_fecha ON "auditoriausuarios" (fecha DESC);
CREATE INDEX IF NOT EXISTS ix_auditoriausuariosarchivo_fecha ON "auditoriausuariosarchivo" (fecha DESC);
CREATE INDEX IF NOT EXISTS ix_listanegra_placaactivo ON "listanegra" (placa, activo);
CREATE INDEX IF NOT EXISTS ix_vehiculosautorizados_placaactivo ON "vehiculosautorizados" (placa, activo);
CREATE INDEX IF NOT EXISTS ix_deteccion_camara_fecha ON "deteccionvehiculo" (camara_id, fecha_hora_ingreso DESC);
CREATE INDEX IF NOT EXISTS ix_deteccion_estado ON "deteccionvehiculo" (estado_validacion, estado_procesamiento);
CREATE INDEX IF NOT EXISTS ix_deteccion_fechahora ON "deteccionvehiculo" (fecha_hora_ingreso DESC);
CREATE INDEX IF NOT EXISTS ix_deteccion_placa ON "deteccionvehiculo" (placa_reconocida);
CREATE INDEX IF NOT EXISTS ix_deteccion_placavalidada ON "deteccionvehiculo" (placa_validada);
CREATE INDEX IF NOT EXISTS ix_deteccion_validacion_fecha ON "deteccionvehiculo" (validado_manualmente, fecha_hora_ingreso);
CREATE INDEX IF NOT EXISTS ix_notificaciones_dedup ON "notificaciones" (clave_dedup, fecha_creacion DESC);
CREATE INDEX IF NOT EXISTS ix_notificaciones_deteccion ON "notificaciones" (deteccion_id);
CREATE INDEX IF NOT EXISTS ix_notificaciones_fecha ON "notificaciones" (fecha_creacion DESC);
CREATE INDEX IF NOT EXISTS ix_notificaciones_pendientes ON "notificaciones" (requiere_ack, fecha_atencion, escalada, fecha_creacion);
CREATE INDEX IF NOT EXISTS ix_notificacionusuario_bandeja ON "notificacionusuario" (usuario_id, notificacion_id DESC) INCLUDE (fecha_lectura);
CREATE INDEX IF NOT EXISTS ix_restablecimientopassword_token ON "restablecimientopassword" (token_hash);
CREATE INDEX IF NOT EXISTS ix_solicitudesacceso_estado ON "solicitudesacceso" (estado, fecha_solicitud DESC);
CREATE INDEX IF NOT EXISTS ix_solicitudesacceso_placa ON "solicitudesacceso" (placa, estado);
CREATE INDEX IF NOT EXISTS ix_suscripcionespush_usuario ON "suscripcionespush" (usuario_id);
CREATE INDEX IF NOT EXISTS ix_verificacionemail_token ON "verificacionemail" (token_hash);

INSERT INTO "roles" (codigo, nombre, descripcion) VALUES
  ('ADMIN', 'Administrador', 'Gestión total del sistema.'),
  ('GUARDIA', 'Guardia', 'Monitoreo y validación de ingresos.'),
  ('GESTOR_PERMISOS', 'Gestor de permisos', 'Gestión de permisos y solicitudes.')
ON CONFLICT (codigo) DO NOTHING;
